def _require(package_name: str, feature: str):
    """尝试导入包，失败时报"缺依赖不可用"并退出（不自动安装）。"""
    try:
        __import__(package_name)
    except ImportError:
        print(f"❌ 缺少依赖: {package_name}（{feature} 不可用）")
        sys.exit(1)

